import { Controller } from "@hotwired/stimulus"

const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000

export default class extends Controller {
  static values = { style: { type: String, default: "datetime" } }

  connect() {
    const date = new Date(this.element.dateTime)

    if (!Number.isNaN(date.valueOf())) {
      this.element.textContent = this.#formattedDate(date)
      this.element.title = this.#exactDateTime(date)
    }
  }

  #formattedDate(date) {
    switch (this.styleValue) {
      case "time":
        return this.#time(date)
      case "date":
        return this.#date(date)
      case "weekday-date":
        return this.#weekdayDate(date)
      case "numeric-datetime":
        return this.#numericDateTime(date)
      default:
        return this.#relativeDateTime(date)
    }
  }

  #relativeDateTime(date) {
    const days = this.#differenceInCalendarDays(date)

    if (days === 0) return this.#time(date)
    if (days === -1) return "yesterday"
    if (days === 1) return "tomorrow"
    if (days < 0 && days >= -6) return `${Math.abs(days)} days ago`
    if (days > 0 && days <= 6) return `in ${days} days`

    return this.#date(date)
  }

  #differenceInCalendarDays(date) {
    const today = new Date()
    const localDate = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate())
    const localToday = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate())

    return Math.round((localDate - localToday) / DAY_IN_MILLISECONDS)
  }

  #time(date) {
    return new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(date)
  }

  #date(date) {
    const options = { month: "short", day: "numeric" }
    if (date.getFullYear() !== new Date().getFullYear()) options.year = "numeric"

    return new Intl.DateTimeFormat(undefined, options).format(date)
  }

  #weekdayDate(date) {
    return new Intl.DateTimeFormat(undefined, { weekday: "long", month: "long", day: "numeric" }).format(date)
  }

  #numericDateTime(date) {
    return new Intl.DateTimeFormat(undefined, {
      year: "2-digit", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit"
    }).format(date)
  }

  #exactDateTime(date) {
    return new Intl.DateTimeFormat(undefined, {
      dateStyle: "full", timeStyle: "short"
    }).format(date)
  }
}
EOF
